      if(!row.hidden)count++;
    });
    document.getElementById('ux-writing-empty').hidden=count>0;directory.querySelector('.ww-directory-count').textContent=count?'共 '+count+' 道 · 选择题目即可开始首稿或继续已有稿':'没有匹配的题目，试试其他关键词或Task。';
  }
